#include <string>
using namespace std;

vector<int> rabinKarp(string text, string pattern) {
    int n = text.length(), m = pattern.length();
    if (m > n) return {};
    long long BASE = 256, MOD = 101, h = 1, pHash = 0, tHash = 0;
    vector<int> matches;
    for (int i = 0; i < m - 1; i++) h = (h * BASE) % MOD;
    for (int i = 0; i < m; i++) {
        pHash = (BASE * pHash + pattern[i]) % MOD;
        tHash = (BASE * tHash + text[i]) % MOD;
    }
    for (int i = 0; i <= n - m; i++) {
        if (pHash == tHash && text.substr(i, m) == pattern) matches.push_back(i);
        if (i < n - m) {
            tHash = (BASE * (tHash - text[i] * h) + text[i + m]) % MOD;
            if (tHash < 0) tHash += MOD;
        }
    }
    return matches;
}

def z_algorithm(text, pattern):
    concat = pattern + '$' + text
    n = len(concat)
    z = [0] * n
    l, r, k = 0, 0, 0
    for i in range(1, n):
        if i > r:
            l, r = i, i
            while r < n and concat[r - l] == concat[r]:
                r += 1
            z[i] = r - l
            r -= 1
        else:
            k = i - l
            if z[k] < r - i + 1:
                z[i] = z[k]
            else:
                l = i
                while r < n and concat[r - l] == concat[r]:
                    r += 1
                z[i] = r - l
                r -= 1
    matches = []
    pat_len = len(pattern)
    for i in range(pat_len + 1, n):
        if z[i] == pat_len:
            matches.append(i - pat_len - 1)
    return matches

def longest_palindrome(s):
    res = ''
    for i in range(len(s)):
        # Odd length palindromes
        l, r = i, i
        while l >= 0 and r < len(s) and s[l] == s[r]:
            if (r - l + 1) > len(res):
                res = s[l:r+1]
            l -= 1; r += 1
        # Even length palindromes
        l, r = i, i + 1
        while l >= 0 and r < len(s) and s[l] == s[r]:
            if (r - l + 1) > len(res):
                res = s[l:r+1]
            l -= 1; r += 1
    return res

class StringHasher:
    def __init__(self, s, P=31, MOD=10**9 + 7):
        self.MOD = MOD
        n = len(s)
        self.pref = [0] * (n + 1)
        self.pow_p = [1] * (n + 1)
        for i in range(n):
            self.pref[i+1] = (self.pref[i] * P + ord(s[i])) % MOD
            self.pow_p[i+1] = (self.pow_p[i] * P) % MOD

    def get_hash(self, l, r):
        val = (self.pref[r+1] - self.pref[l] * self.pow_p[r - l + 1]) % self.MOD
        return (val + self.MOD) % self.MOD
